css:
/* From Uiverse.io by Spacious74  - Tags: simple, login, subscription, email, minimalist, form, register, signin */
.__UIV_SCOPE__ .container {
  border: solid 1px #8d8d8d;
  padding: 20px;
  border-radius: 20px;
  background-color: #fff;
}

.__UIV_SCOPE__ .container .heading {
  font-size: 1.3rem;
  margin-bottom: 20px;
  font-weight: bolder;
}

.__UIV_SCOPE__ .form {
  max-width: 300px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.__UIV_SCOPE__ .form .btn-container {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 20px;
}

.__UIV_SCOPE__ .form .btn {
  padding: 10px 20px;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 3px;
  border-radius: 10px;
  border: solid 1px #1034aa;
  border-bottom: solid 1px #90c2ff;
  background: linear-gradient(135deg, #0034de, #006eff);
  color: #fff;
  font-weight: bolder;
  transition: all 0.2s ease;
  box-shadow: 0px 2px 3px #000d3848, inset 0px 4px 5px #0070f0,
    inset 0px -4px 5px #002cbb;
}

.__UIV_SCOPE__ .form .btn:active {
  box-shadow: inset 0px 4px 5px #0070f0, inset 0px -4px 5px #002cbb;
  transform: scale(0.995);
}

.__UIV_SCOPE__ .input-field {
  position: relative;
}

.__UIV_SCOPE__ .input-field label {
  position: absolute;
  color: #8d8d8d;
  pointer-events: none;
  background-color: transparent;
  left: 15px;
  transform: translateY(0.6rem);
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .input-field input {
  padding: 10px 15px;
  font-size: 1rem;
  border-radius: 8px;
  border: solid 1px #8d8d8d;
  letter-spacing: 1px;
  width: 100%;
}

.__UIV_SCOPE__ .input-field input:focus,
.__UIV_SCOPE__ .input-field input:valid {
  outline: none;
  border: solid 1px #0034de;
}

.__UIV_SCOPE__ .input-field input:focus ~ label,
.__UIV_SCOPE__ .input-field input:valid ~ label {
  transform: translateY(-51%) translateX(-10px) scale(0.8);
  background-color: #fff;
  padding: 0px 5px;
  color: #0034de;
  font-weight: bold;
  letter-spacing: 1px;
  border: none;
  border-radius: 100px;
}

.__UIV_SCOPE__ .form .passicon {
  cursor: pointer;
  font-size: 1.3rem;
  position: absolute;
  top: 6px;
  right: 8px;
}

.__UIV_SCOPE__ .form .close {
  display: none;
}
